using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PhotonGloveOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PhotonGlove Omen Data")]
public class PhotonGloveOmenData : OmenData
{
	[Serializable]
	public class PhotonGloveValues
	{
		public DiceTier diceTier;

		public int purifyIncreaseAmount;
	}

	[Header("Azimuth Ring")]
	[SerializeField]
	private List<PhotonGloveValues> photonGloveValues;

	private Func<int, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int purifyAmount)
		{
			ActionInstance lateCurrentActionInstance = ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance;
			if (lateCurrentActionInstance != null && lateCurrentActionInstance is DiceInstance)
			{
				DiceInstance diceInstance = lateCurrentActionInstance as DiceInstance;
				for (int i = 0; i < photonGloveValues.Count; i++)
				{
					if (photonGloveValues[i].diceTier == diceInstance.Dice.DiceTier)
					{
						omenInstance.PlayOmenShakeFeedback();
						return purifyAmount + photonGloveValues[i].purifyIncreaseAmount;
					}
				}
			}
			return purifyAmount;
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifierOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		string text = "";
		for (int i = 0; i < photonGloveValues.Count; i++)
		{
			string localizedDiceTierWithDie = photonGloveValues[i].diceTier.GetLocalizedDiceTierWithDie();
			text += Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IncreasePurificationDealtBySpecificDie"), localizedDiceTierWithDie, photonGloveValues[i].purifyIncreaseAmount);
			if (i < photonGloveValues.Count - 1)
			{
				text += "\n";
			}
		}
		return text;
	}
}
